import hashlib
import json
from pathlib import Path
import re
import subprocess

base = Path('build/jit-views')
frozen = json.loads((base / 'frozen-candidate-inputs.json').read_text())
def verify():
    for path, digest in frozen.items():
        assert hashlib.sha256(Path(path).read_bytes()).hexdigest() == digest, path
verify()
for suffix, count in [('full-on', 93), ('full-off', 86), ('asan', 9), ('x86', 8)]:
    log = Path('/tmp/mmay-jit-views-' + suffix + '-tests.log').read_text()
    assert re.search(r'100% tests passed(?:, 0 tests failed)? out of ' + str(count) + r'\b', log)
for suffix in ('asan', 'x86'):
    assert json.loads((base / (suffix + '-all32-correctness.json')).read_text())['status'] == 'passed'
assert 'All validation completed;' in Path('/tmp/mmay-jit-views-validation.log').read_text()

participants = {
    'jit': ('build/vm-preparation-paired/run-more4x5i/toolchain/bin/mmay', 'build/jit-views/mmay'),
    'interpreter': ('build/release/mmay', 'build/jit-views-off/mmay'),
}
def run(kind, workload=None):
    before, after = participants[kind]
    output = base / (kind + '-' + (workload + '-confirmation' if workload else 'paired32') + '.json')
    command = ['python3', 'tools/performance/compare-vm-preparation.py', '--benchmarks', '../algorithm-benchmarks',
        '--reference', 'docs/implementation/evidence/cp42-vm-preparation-comprehensive-2026-09-09.json',
        '--before', before, '--after', after, '--output', str(output)]
    if workload: command += ['--workload', workload]
    print('Starting', kind, workload or 'full32', flush=True)
    output.with_suffix('.command.json').write_text(json.dumps(command, indent=2) + '\n')
    with output.with_suffix('.log').open('w') as log:
        subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, check=True)
    print(output.with_suffix('.log').read_text(), flush=True)
    verify()
    return json.loads(output.read_text())

def p90(raw):
    xs = sorted(raw)
    assert len(xs) == 11
    position = .9 * (len(xs) - 1)
    lo = int(position)
    return xs[lo] + (xs[min(lo + 1, len(xs) - 1)] - xs[lo]) * (position - lo)

def ratios(result, name):
    x = result['summary'][name]
    return {'median': x['after']['median_ms'] / x['before']['median_ms'],
            'p90': p90(result['raw_ms'][name]['after']) / p90(result['raw_ms'][name]['before'])}

results = {kind: run(kind) for kind in participants}
limits = {'median': 1.02, 'p90': 1.05}
decisions = {}
for kind, result in results.items():
    flagged = {name: ratios(result, name) for name in result['summary']
               if any(ratios(result, name)[key] > limit for key, limit in limits.items())}
    decisions[kind] = {}
    print(kind, 'single planned confirmations', flagged, flush=True)
    for name, first in flagged.items():
        repeat = run(kind, name)
        second = ratios(repeat, name)
        confirmed = [key for key, limit in limits.items() if first[key] > limit and second[key] > limit]
        decisions[kind][name] = {'full': first, 'confirmation': second, 'confirmed_regressions': confirmed}
        (base / 'confirmation-outcomes.json').write_text(json.dumps(decisions, indent=2) + '\n')
(base / 'confirmation-outcomes.json').write_text(json.dumps(decisions, indent=2) + '\n')
print('All full matrices and predeclared confirmations completed.', flush=True)
